import pytest

from cfnlint.rules.resources.stepfunctions.StateMachineDefinition import (
    StateMachineDefinition,
)


@pytest.fixture(scope="module")
def rule():
    yield StateMachineDefinition()


def test_inline_map_itemprocessor(rule, validator):
    instance = {
        "StartAt": "HelloWorld",
        "States": {
            "Validate_All": {
                "Type": "Map",
                "InputPath": "$.detail",
                "ItemProcessor": {
                    "ProcessorConfig": {"Mode": "INLINE"},
                    "StartAt": "Validate",
                    "States": {
                        "Validate": {"Type": "Pass", "End": True}
                    },
                },
                "End": True,
                "ResultPath": "$.dtail.shipped",
                "ItemsPath": "$.shipped",
            }
        },
    }
    errs = list(rule.validate(validator, {}, instance, {}))
    assert errs == []


def test_fail_cause_error_paths(rule, validator):
    instance = {
        "StartAt": "FailState",
        "States": {
            "FailState": {
                "Type": "Fail",
                "CausePath": "$.Cause",
                "ErrorPath": "$.Error",
            }
        },
    }
    errs = list(rule.validate(validator, {}, instance, {}))
    assert errs == []


def test_choice_is_present_and_equals_path(rule, validator):
    instance = {
        "StartAt": "ChoiceState",
        "States": {
            "ChoiceState": {
                "Type": "Choice",
                "Choices": [
                    {"Variable": "$.v", "NumericEquals": 0, "Next": "SucceedState"},
                    {"Variable": "$.v", "IsPresent": True, "Next": "SucceedState"},
                    {"Variable": "$.t", "StringEqualsPath": "$.path", "Next": "SucceedState"},
                ],
                "Default": "SucceedState",
            },
            "SucceedState": {"Type": "Succeed"},
        },
    }
    errs = list(rule.validate(validator, {}, instance, {}))
    assert errs == []


def test_task_timeout_heartbeat_paths(rule, validator):
    instance = {
        "StartAt": "TaskState",
        "States": {
            "TaskState": {
                "Type": "Task",
                "Resource": "arn:aws:states:::lambda:invoke",
                "TimeoutSecondsPath": "$.TimeutSeconds",
                "HeartbeatSecondsPath": "$.HeartbeatSeconds",
                "End": True,
            }
        },
    }
    errs = list(rule.validate(validator, {}, instance, {}))
    assert errs == []
